const productData = $('Get Active Products').item.json;
const html = $input.item.json.data || '';

// For Amazon: find the FIRST price that appears after 'corePrice' or 'a-price' class
// This is typically the main buybox price
let extractedPrice = null;

// Method 1: Look for a-offscreen price (hidden accessible price, usually accurate)
const offscreenPrices = html.match(/a-offscreen["'][^>]*>([€$£])?\s*([\d,.]+)/gi);
if (offscreenPrices && offscreenPrices.length > 0) {
  // Get first offscreen price (usually the main product price)
  const firstPrice = offscreenPrices[0];
  const priceNum = firstPrice.match(/([\d]+[,.]\d{2})/);
  if (priceNum) {
    extractedPrice = parseFloat(priceNum[1].replace(',', '.'));
  }
}

// Method 2: Look for price in corePrice section
if (!extractedPrice) {
  const corePriceSection = html.match(/corePrice[\s\S]{0,500}?([\d]+[,.]\d{2})\s*€/i);
  if (corePriceSection) {
    extractedPrice = parseFloat(corePriceSection[1].replace(',', '.'));
  }
}

// Method 3: Look for € followed by price
if (!extractedPrice) {
  const euroPrice = html.match(/€\s*([\d]+[,.]\d{2})/i);
  if (euroPrice) {
    extractedPrice = parseFloat(euroPrice[1].replace(',', '.'));
  }
}

// Clean HTML for GPT (cut before 'Featured items' or 'Customers also')
let cleanHtml = html;
const featuredIndex = html.indexOf('Featured items you may like');
const customersIndex = html.indexOf('Customers also');
const similarIndex = html.indexOf('Similar items');

let cutIndex = html.length;
if (featuredIndex > 5000 && featuredIndex < cutIndex) cutIndex = featuredIndex;
if (customersIndex > 5000 && customersIndex < cutIndex) cutIndex = customersIndex;
if (similarIndex > 5000 && similarIndex < cutIndex) cutIndex = similarIndex;

cleanHtml = html.substring(0, cutIndex)
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&[a-z]+;/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim();

if (cleanHtml.length > 8000) {
  cleanHtml = cleanHtml.substring(0, 8000);
}

let priceHint = '';
if (extractedPrice) {
  priceHint = `IMPORTANT: The main product price is ${extractedPrice} EUR. Use this exact price.\n\n`;
}

const prompt = `${priceHint}Extract product info and return JSON only:
{"price": ${extractedPrice || '<number>'}, "currency": "EUR", "productName": "<name>", "inStock": <true/false/null>}

Rules: Use the price shown above if provided. Return ONLY valid JSON.

Text: ${cleanHtml}`;

return {
  productData: productData,
  prompt: prompt,
  extractedPrice: extractedPrice
};

const productData = $('Prepare GPT Prompt').item.json.productData;
const extractedPrice = $('Prepare GPT Prompt').item.json.extractedPrice;
const openaiResponse = $input.item.json;

let extracted = { price: null, currency: 'EUR', productName: null, inStock: null };

try {
  let gptText = openaiResponse.choices[0].message.content.trim();
  gptText = gptText.replace(/```json\n?/g, '').replace(/```\n?/g, '');
  const jsonMatch = gptText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    extracted = JSON.parse(jsonMatch[0]);
  }
} catch (e) {}

// Prefer our extracted price if GPT gives something different
let currentPrice = typeof extracted.price === 'number' ? extracted.price : null;
if (extractedPrice && currentPrice !== extractedPrice) {
  currentPrice = extractedPrice;
}

const targetPrice = parseFloat(productData.targetPrice);
const shouldNotify = currentPrice !== null && currentPrice <= targetPrice;

return {
  productId: productData.id,
  url: productData.url,
  productName: extracted.productName || productData.productName,
  email: productData.email,
  targetPrice: targetPrice,
  currentPrice: currentPrice,
  currency: extracted.currency || 'EUR',
  inStock: extracted.inStock,
  priceFound: currentPrice !== null,
  shouldNotify: shouldNotify
};

